import React from 'react';

/** Visual variant for the Card. */
export type CardVariant = 'solid' | 'dither' | 'outline' | 'ghost' | 'inverted' | 'pixel';

/** Props for the {@link Card} component. */
export interface CardProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Visual variant of the card surface. */
  variant?: CardVariant;
  /** Additional CSS class names. */
  className?: string;
  children?: React.ReactNode;
}

/**
 * Elevated container with dither surface.
 * Renders a `<div>` with the `sk-card` class.
 */
export const Card = React.forwardRef<HTMLDivElement, CardProps>(
  ({ variant, className, children, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-card${className ? ` ${className}` : ''}`}
      data-variant={variant}
      {...rest}
    >
      {children}
    </div>
  ),
);

Card.displayName = 'Card';

/** Props for the {@link CardHeader} sub-component. */
export interface CardHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Header section of a Card with a subtle scanline texture. */
export const CardHeader = React.forwardRef<HTMLDivElement, CardHeaderProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-card__header${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

CardHeader.displayName = 'CardHeader';

/** Props for the {@link CardTitle} sub-component. */
export interface CardTitleProps extends React.HTMLAttributes<HTMLHeadingElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Title element inside a CardHeader. */
export const CardTitle = React.forwardRef<HTMLHeadingElement, CardTitleProps>(
  ({ className, children, ...rest }, ref) => (
    <h3 ref={ref} className={`sk-card__title${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </h3>
  ),
);

CardTitle.displayName = 'CardTitle';

/** Props for the {@link CardBody} sub-component. */
export interface CardBodyProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Body / main content area of a Card. */
export const CardBody = React.forwardRef<HTMLDivElement, CardBodyProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-card__body${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

CardBody.displayName = 'CardBody';

/** Props for the {@link CardFooter} sub-component. */
export interface CardFooterProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Footer section of a Card. */
export const CardFooter = React.forwardRef<HTMLDivElement, CardFooterProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-card__footer${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

CardFooter.displayName = 'CardFooter';

/**
 * skeehn — Card Component
 *
 * @component sk-card
 * @variants  solid | dither | outline | ghost | inverted | pixel | retro | ascii
 * @states    :hover | :focus-within | [data-loading] | [data-skeleton] | [data-interactive]
 * @slots     __header | __title | __eyebrow | __meta | __body | __footer | __footer-text
 * @a11y      Semantic section with clear focus ring + reduced-motion fallback
 * @print     Flat borders, no overlays or glows
 */

.sk-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: clip;
  border: var(--sk-border);
  border-radius: var(--sk-radius-panel);
  background: var(--sk-panel-gradient);
  color: hsl(var(--sk-foreground));
  box-shadow: var(--sk-panel-shadow);
  isolation: isolate;
  transition:
    box-shadow var(--sk-transition-slow),
    transform var(--sk-transition),
    border-color var(--sk-transition-fast),
    background-color var(--sk-transition-fast);
}

.sk-card::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at top right, hsl(var(--sk-foreground) / 0.045), transparent 42%),
    linear-gradient(180deg, hsl(var(--sk-background) / 0.32), transparent 42%);
  opacity: 0.8;
  z-index: 0;
}

.sk-card > * {
  position: relative;
  z-index: 1;
}

.sk-card:hover,
.sk-card:focus-within,
.sk-card[data-interactive="true"]:hover,
.sk-card[data-interactive="true"]:focus-within {
  transform: translateY(-2px);
  border-color: hsl(var(--sk-foreground) / 0.25);
  box-shadow:
    0 24px 46px hsl(0 0% 0% / 0.28),
    inset 0 1px 0 hsl(0 0% 100% / 0.12);
}
.sk-card[data-interactive="true"]:focus-visible {
  outline: var(--sk-focus-ring);
  outline-offset: 2px;
}

.sk-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sk-space-2);
  padding: var(--sk-space-4) var(--sk-space-5) var(--sk-space-3);
  border-bottom: var(--sk-border);
  background:
    linear-gradient(180deg, hsl(var(--sk-muted) / 0.6), transparent),
    repeating-linear-gradient(
      to bottom,
      transparent 0,
      transparent 3px,
      hsl(var(--sk-foreground) / 0.025) 3px,
      hsl(var(--sk-foreground) / 0.025) 4px
    );
}

.sk-card__eyebrow {
  margin: 0;
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground));
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.sk-card__title {
  margin: 0;
  font-family: var(--sk-font-sans);
  font-size: var(--sk-font-size-lg);
  font-weight: var(--sk-font-weight-semi);
  letter-spacing: var(--sk-letter-spacing-tight);
  line-height: var(--sk-line-height-tight);
}

.sk-card__meta {
  margin: 0;
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground));
  white-space: nowrap;
}

.sk-card__body,
.sk-card__content {
  padding: var(--sk-space-5);
}

.sk-card__body > :first-child,
.sk-card__content > :first-child {
  margin-top: 0;
}

.sk-card__body > :last-child,
.sk-card__content > :last-child {
  margin-bottom: 0;
}

.sk-card__body p,
.sk-card__content p {
  margin: 0;
  color: hsl(var(--sk-muted-foreground));
  font-size: var(--sk-font-size-sm);
  line-height: 1.7;
}

.sk-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sk-space-2);
  padding: var(--sk-space-3) var(--sk-space-5) var(--sk-space-4);
  border-top: var(--sk-border);
  background: hsl(var(--sk-muted) / 0.35);
}

.sk-card__footer-text {
  margin: 0;
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-muted-foreground));
  letter-spacing: 0.02em;
}

.sk-card[data-variant="solid"] {
  background: hsl(var(--sk-background));
}

.sk-card[data-variant="dither"] {
  background: hsl(var(--sk-background));
}

.sk-card[data-variant="dither"]::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    var(--sk-dither-pattern),
    radial-gradient(circle at 10% 0%, hsl(var(--sk-foreground) / 0.05), transparent 36%);
  background-size: 32px 32px, auto;
  opacity: 0.18;
  mix-blend-mode: multiply;
  pointer-events: none;
  z-index: 0;
}

.sk-card[data-variant="outline"] {
  background: transparent;
  border-width: 2px;
}

.sk-card[data-variant="ghost"] {
  background: hsl(var(--sk-accent));
  border-color: transparent;
  box-shadow: none;
}

.sk-card[data-variant="ghost"]::before {
  opacity: 0.45;
}

.sk-card[data-variant="inverted"] {
  border-color: transparent;
  background: hsl(var(--sk-foreground));
  color: hsl(var(--sk-background));
}

.sk-card[data-variant="inverted"]::before {
  background: linear-gradient(180deg, hsl(var(--sk-background) / 0.09), transparent 46%);
}

.sk-card[data-variant="inverted"] .sk-card__title,
.sk-card[data-variant="inverted"] .sk-card__footer-text {
  color: hsl(var(--sk-background));
}

.sk-card[data-variant="inverted"] .sk-card__eyebrow,
.sk-card[data-variant="inverted"] .sk-card__meta,
.sk-card[data-variant="inverted"] .sk-card__body p,
.sk-card[data-variant="inverted"] .sk-card__content p {
  color: hsl(var(--sk-background) / 0.72);
}

.sk-card[data-variant="inverted"] .sk-card__header,
.sk-card[data-variant="inverted"] .sk-card__footer {
  border-color: hsl(var(--sk-background) / 0.12);
}

.sk-card[data-variant="pixel"] {
  border: 2px solid hsl(var(--sk-foreground));
  box-shadow: 6px 6px 0 hsl(var(--sk-foreground));
}

.sk-card[data-variant="pixel"]:hover,
.sk-card[data-variant="pixel"]:focus-within {
  transform: translate(-2px, -2px);
  box-shadow: 8px 8px 0 hsl(var(--sk-foreground));
}

.sk-card[data-variant="retro"] {
  border: 2px solid hsl(var(--sk-foreground));
  box-shadow:
    0 0 0 1px hsl(var(--sk-foreground) / 0.1),
    0 0 20px hsl(var(--sk-foreground) / 0.08),
    inset 0 0 24px hsl(var(--sk-foreground) / 0.04);
}

.sk-card[data-variant="retro"]::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 2px,
    hsl(var(--sk-foreground) / 0.04) 2px,
    hsl(var(--sk-foreground) / 0.04) 3px
  );
  pointer-events: none;
  z-index: 0;
}

.sk-card[data-variant="ascii"] {
  border: none;
  background: transparent;
  box-shadow: none;
  padding: var(--sk-space-2) 0;
}

.sk-card[data-variant="ascii"]::before,
.sk-card[data-variant="ascii"]::after {
  position: static;
  display: block;
  font-family: var(--sk-font-mono);
  font-size: 0.5rem;
  line-height: 1;
  letter-spacing: 0;
  color: hsl(var(--sk-border-color));
  background: none;
  opacity: 1;
}

.sk-card[data-variant="ascii"]::before {
  content: "┌──────────────────────────────┐";
}

.sk-card[data-variant="ascii"]::after {
  content: "└──────────────────────────────┘";
}

.sk-card[data-variant="ascii"] .sk-card__header,
.sk-card[data-variant="ascii"] .sk-card__footer {
  border: none;
  background: transparent;
  padding-inline: var(--sk-space-2);
}

@keyframes sk-card-dither-fill {
  0% {
    background-image: var(--sk-dither-b2);
    opacity: 0.05;
  }
  50% {
    background-image: var(--sk-dither-b8);
    opacity: 0.12;
  }
  100% {
    background-image: var(--sk-dither-b2);
    opacity: 0.05;
  }
}

@keyframes sk-card-shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.sk-card[data-loading] {
  pointer-events: none;
}

.sk-card[data-loading] .sk-card__body,
.sk-card[data-loading] .sk-card__content {
  position: relative;
}

.sk-card[data-loading] .sk-card__body::after,
.sk-card[data-loading] .sk-card__content::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  animation: sk-card-dither-fill 1.6s steps(4) infinite;
  pointer-events: none;
}

.sk-card[data-skeleton] {
  pointer-events: none;
}

.sk-card[data-skeleton] .sk-card__title,
.sk-card[data-skeleton] .sk-card__eyebrow,
.sk-card[data-skeleton] .sk-card__body p,
.sk-card[data-skeleton] .sk-card__content p,
.sk-card[data-skeleton] .sk-card__footer-text {
  color: transparent;
  border-radius: var(--sk-radius-control);
  background: linear-gradient(
    90deg,
    hsl(var(--sk-muted)) 20%,
    hsl(var(--sk-accent)) 50%,
    hsl(var(--sk-muted)) 80%
  );
  background-size: 200% 100%;
  animation: sk-card-shimmer 1.5s ease-in-out infinite;
}

@media print {
  .sk-card {
    box-shadow: none;
    border: 1px solid hsl(var(--sk-foreground));
    break-inside: avoid;
    transform: none;
  }

  .sk-card::before,
  .sk-card::after {
    display: none;
  }

  .sk-card[data-skeleton],
  .sk-card[data-loading] {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sk-card {
    transition: none;
  }

  .sk-card:hover,
  .sk-card:focus-within,
  .sk-card[data-interactive="true"]:hover,
  .sk-card[data-interactive="true"]:focus-within,
  .sk-card[data-variant="pixel"]:hover,
  .sk-card[data-variant="pixel"]:focus-within {
    transform: none;
  }

  .sk-card[data-skeleton] .sk-card__title,
  .sk-card[data-skeleton] .sk-card__eyebrow,
  .sk-card[data-skeleton] .sk-card__body p,
  .sk-card[data-skeleton] .sk-card__content p,
  .sk-card[data-skeleton] .sk-card__footer-text {
    animation: none;
    background: hsl(var(--sk-muted));
  }

  .sk-card[data-loading] .sk-card__body::after,
  .sk-card[data-loading] .sk-card__content::after {
    animation: none;
  }
}
